// Zweck: HTTP-Body validieren und SQLite-Batch-Query für das Löschen eines Geräts vorbereiten.
//
// OPTIMIERUNG: readPayloadObject() war hier als 40-Zeilen-Inline-Funktion dupliziert
// (identisch zu 42_dashboard_device_name). Jetzt kommt sie aus flowHelpers (00_boot).
//
// Sicherheitsanforderung: confirm_delete muss explizit auf true gesetzt sein.
// Das verhindert versehentliches Löschen durch fehlerhafte API-Aufrufe.
//
// Eingabe:  msg.payload oder msg.req.body – { device_id, confirm_delete: true }
// Ausgaben:
//   Output 1 – msg mit SQL-Batch → weiter zum SQLite-Node
//   Output 2 – HTTP-Fehlerantwort (400/500)

const dashboard   = global.get("dashboardV1");
const flowHelpers = global.get("flowHelpers");

if (!dashboard || typeof dashboard.buildDeviceDeleteQuery !== "function") {
    msg.statusCode = 500;
    msg.payload    = { ok: false, error: "dashboard_helper_missing", message: "dashboardV1 helper fehlt" };
    return [null, msg];
}
if (!flowHelpers) {
    msg.statusCode = 500;
    msg.payload    = { ok: false, error: "flow_helpers_unavailable", message: "Boot-Flow prüfen" };
    return [null, msg];
}

// Payload aus msg.payload ODER msg.req.body lesen (je nach Content-Type-Parsing).
// flowHelpers.readPayloadObject kümmert sich um JSON-String, Buffer und fertiges Objekt.
const bodyPayload = (msg.payload && typeof msg.payload === "object" && !Buffer.isBuffer(msg.payload))
    ? msg.payload
    : (msg.req && msg.req.body ? msg.req.body : msg.payload);
const payload = flowHelpers.readPayloadObject(bodyPayload);

// Pflichtfeld device_id.
const deviceId = typeof payload.device_id === "string" ? payload.device_id.trim() : "";
if (!deviceId) {
    msg.statusCode = 400;
    msg.payload    = { ok: false, error: "device_id_required", message: "device_id ist ein Pflichtfeld" };
    return [null, msg];
}

// Explizite Bestätigung verhindern versehentliches Löschen.
if (payload.confirm_delete !== true) {
    msg.statusCode = 400;
    msg.payload    = { ok: false, error: "delete_not_confirmed", message: "confirm_delete: true ist erforderlich" };
    return [null, msg];
}

// SQL-Batch aus der Dashboard-Lib bauen (löscht devices + device_state_latest).
const deleteQuery = dashboard.buildDeviceDeleteQuery(deviceId);
if (!deleteQuery) {
    msg.statusCode = 400;
    msg.payload    = { ok: false, error: "invalid_device_id", message: "device_id ist ungültig" };
    return [null, msg];
}

// Merker für die Response-Function nach dem SQLite-Aufruf.
msg.deleteDeviceId       = deviceId;
msg.deleteDeviceResponse = { ok: true, device_id: deviceId, message: "Gerät gelöscht" };
msg.topic                = deleteQuery;
return [msg, null];

// Zweck: Nach erfolgreichem DB-Löschen das Gerät aus dem Runtime-Cache entfernen
// und retained MQTT-Topics bereinigen.
//
// Warum zwei Schritte?
//   1. DB-Löschung ist bereits durch den SQLite-Node abgeschlossen.
//   2. Runtime-Cache muss manuell aktualisiert werden (kein DB-Trigger).
//   3. Retained Topics bleiben sonst dauerhaft auf dem Broker erhalten.
//
// Ausgaben:
//   Output 1 – HTTP-Antwort (200 OK)
//   Output 2 – Array von leeren Retained-Messages für jeden Topic-Block

const deviceId = msg.deleteDeviceId || "";
const runtime  = global.get("smarthome_runtime");

// Gerät aus dem In-Memory-Cache entfernen.
if (deviceId && runtime && runtime.devices &&
    Object.prototype.hasOwnProperty.call(runtime.devices, deviceId)) {
    delete runtime.devices[deviceId];
    global.set("smarthome_runtime", runtime);
}

// Leere retained Messages bauen: jeder Block (meta, availability, ...) wird
// mit leerem Payload und retain=true überschrieben → Broker löscht das retained Topic.
const topicBlocks = ["meta", "availability", "state", "event", "ack"];
const clearRetainedMessages = deviceId
    ? topicBlocks.map((block) => ({
        topic:   `smarthome/device/${deviceId}/${block}`,
        payload: "",
        qos:     0,
        retain:  true
    }))
    : [];

msg.statusCode = 200;
msg.payload    = msg.deleteDeviceResponse || { ok: true, device_id: deviceId, message: "Gerät gelöscht" };
return [msg, clearRetainedMessages];
